+            "runner-temp" => {
+                let link = root.0.join("runner-temp-link");
+                symlink(&external, &link)?;
+                link
+            }
+            _ => root.0.clone(),
+        };
+        if location == "velnor-root" {
+            symlink(&external, runner_temp.join("velnor"))?;
+        } else if location == "store-root" {
+            fs::create_dir(runner_temp.join("velnor"))?;
