+            "mr-boxington@1.21.1",
+        ]
+        .into_iter()
+        .map(str::to_owned)
+        .collect(),
+        None,
+    )?;
+    for literal in [";", "&&", "||", "|", "then", "if"] {
+        let script = format!(
+            "printf '%s\\n' '{literal}' mise --no-config --no-env --no-hooks install mr-boxington@1.21.1"
+        );
+        let decoy = shell_step(
