+        let jobs = BTreeMap::from([job("decoy", "Decoy", Vec::new(), vec![decoy])]);
+        check_mbx_gating(&jobs, &BTreeMap::new())?;
+    }
+    let escaped = shell_step(
+        "Print an escaped command example",
+        vec![
+            "sh".to_owned(),
+            "-c".to_owned(),
